pub struct ConcreteSchema { document: Value }
impl ConcreteSchema {
    pub fn patched(&self, ops: &Value) -> Result<Self, Refusal> { … }   // 欄 ・ id ・ $schema を壊す変更は断る
    pub fn rules(&self) -> Vec<Rule> { … }
    pub fn delegates(&self) -> Vec<Delegate> { … }
}

pub fn create(p: &Ports, path: &str, value: &Value) -> Outcome {
    let concrete = ConcreteTemplate::build(value)?;                        // ドメイン
    validation::use_cases::check::check_and_store(p, path, None, concrete.document())  // サブ機能「検証する」
}
pub fn change(p: &Ports, path: &str, ops: &Value) -> Outcome {
    let before = ConcreteSchema::from_document(p.docs.read(path)?)?;
    validation::use_cases::check::check_and_store(p, path, Some(&before), before.patched(ops)?.document())
}

pub fn validate_instance(doc: &Value, c: &ConcreteSchema, …) -> Vec<Finding> { … }
pub fn calls_for_instance(doc: &Value, c: &ConcreteSchema, path: &str) -> Vec<Call> { … }
pub fn judged(call: &Call, output: &Value, …) -> Result<Vec<Finding>, String> { … }

pub fn check_and_store(p: &Ports, path: &str, before: Option<&Value>, next: Document) -> Outcome {
    let found = results_of(p, &next)?;                     // Resolver ・ Validator
    if introduced(before, &found).any() { return Outcome::refused(…) }
    p.docs.write(path, next)?;                             // ポート：文書を保管する
    Outcome::validated(&found)
}

pub fn verify_all(p: &Ports) -> Outcome { for path in p.docs.list()? { … } }

pub fn rejudge(p: &Ports, path: &str) -> Outcome {
    for call in calls_for_instance(&doc, &concrete, path) {
        if let Some(j) = p.rule_judgments.reusable(&call)? { keep(j); continue }   // 同じ読む値なら使い直す
        let answer = p.delegates.call(&delegate, &call)?;                         // ポート：任せる先に依頼する
        p.rule_judgments.keep(&judged(&call, &answer.output, …)?)?;
    }
}

pub trait KeepRuleJudgments {
    fn reusable(&self, call: &Call) -> Result<Option<RuleJudgment>, String>;
    fn keep(&self, j: &RuleJudgment) -> Result<(), String>;
}

pub trait AskApprovedFields {
    fn approved_fields(&self, t: &Target) -> Result<Vec<Pointer>, String>;
}

pub fn create(p: &Ports, path: &str, schema: &str, value: &Value) -> Outcome { … }
pub fn change(p: &Ports, path: &str, ops: &Value) -> Outcome { … }
pub fn supersede(p: &Ports, path: &str, by: &str) -> Outcome { … }

pub fn record(p: &Ports, r: &RecordRequest) -> Outcome {
    let place = p.commits.workplace()?;               // ポート：確定した姿と比べる（保存と版の管理）
    p.change_records.add(&ChangeRecord::new(r, place)?)
}

pub fn approve(p: &Ports, change: &str, verdict: Verdict, …) -> Outcome { … }
pub fn summarize(p: &Ports, id: &str) -> Outcome { … }
pub fn history(p: &Ports, path: &str) -> Outcome { … }

pub trait KeepChangeRecords {
    fn add(&self, r: &ChangeRecord) -> Result<(), String>;
    fn touching(&self, t: &Target) -> Result<Vec<ChangeRecord>, String>;
    fn pending(&self, place: &WorkPlace) -> Result<Vec<ChangeRecord>, String>;
    fn approve(&self, j: &IntentJudgment) -> Result<(), String>;      // 足していく
}

pub trait StoreDocuments {
    fn read(&self, path: &str) -> Result<Option<Value>, String>;     // 形の崩れた文書も読む
    fn write(&self, path: &str, doc: Document) -> Result<(), String>;  // 集約が返した文書だけ
    fn list(&self) -> Result<Vec<String>, String>;
    fn find(&self, id: &str) -> Result<Option<Value>, String>;
}

pub trait CompareWithCommit {
    fn base(&self) -> Result<Option<String>, String>;
    fn changed(&self) -> Result<Vec<FileChange>, String>;
    fn workplace(&self) -> Result<Option<WorkPlace>, String>;
}

pub trait CallDelegates {
    fn call(&self, d: &Delegate, c: &Call) -> Result<Answer, DelegateError>;  // judging も working も
}

